(function () {

  var KEY = 'snek_saved_state'
  var iframe = document.querySelector('.handheld iframe')
  var saved = false

  // ── listen for state broadcasts from snake ──────────────
  window.addEventListener('message', function (e) {
    if (!e.data || e.data.type !== 'snek-state') return
    localStorage.setItem(KEY, JSON.stringify(e.data.gs))
    saved = true
  })

  // ── on iframe load, send saved state back in ─────────────
  if (iframe) {
    iframe.addEventListener('load', function () {
      var raw = localStorage.getItem(KEY)
      if (!raw) return
      try {
        var gs = JSON.parse(raw)
        // small delay — let snake finish its own init first
        setTimeout(function () {
          iframe.contentWindow.postMessage({ type: 'snek-restore', gs: gs }, '*')
        }, 200)
      } catch (err) { /* bad save, ignore */ }
    })
  }

})()
